function uiCardPrimaryTarget(event){const target=event.target;if(!target?.closest||event.button>0||event.defaultPrevented)return null;const card=target.closest('[data-vehicle-card]');if(!card||target.closest('button,a,input,select,textarea,label,summary,details,[contenteditable="true"],[role="button"]'))return null;if(String(window.getSelection?.()||'').trim())return null;return card.querySelector('.vehicle-open')}
function uiWireSearch(root=document){for(const input of root.querySelectorAll('.search input')){if(input.dataset.uiSearchWired)continue;input.dataset.uiSearchWired='1';input.type='search';input.enterKeyHint='search';const holder=input.closest('.search');const clear=document.createElement('button');clear.type='button';clear.className='search-clear';clear.setAttribute('aria-label','Limpar busca');clear.title='Limpar busca';clear.innerHTML=icon('close');const sync=()=>clear.hidden=!input.value;const reset=()=>{input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()};clear.addEventListener('click',reset);input.addEventListener('input',sync);input.addEventListener('keydown',e=>{if(e.key==='Escape'&&input.value){e.preventDefault();reset()}});holder.append(clear);sync()}}
function uiBindTabs(list,prefix,label){if(!list||list.dataset.uiTabsWired)return;list.dataset.uiTabsWired='1';list.setAttribute('role','tablist');list.setAttribute('aria-label',label);const buttons=Array.from(list.querySelectorAll('button')),active=buttons.find(b=>b.classList.contains('active'))||buttons[0];for(const button of buttons){const key=button.dataset.id||button.dataset.view;button.id=prefix+'-'+key;button.dataset.uiTab=button.id;button.setAttribute('role','tab');button.setAttribute('aria-selected',String(button===active));button.setAttribute('aria-controls',prefix+'-panel');button.removeAttribute('aria-current');button.tabIndex=button===active?0:-1;button.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const at=buttons.indexOf(button),next=e.key==='Home'?buttons[0]:e.key==='End'?buttons.at(-1):buttons[(at+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length];next.focus({preventScroll:true});next.click();Promise.resolve().then(()=>document.getElementById(next.id)?.focus({preventScroll:true}))})}const panel=document.createElement('section');panel.id=prefix+'-panel';panel.className='ui-tab-panel';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',active.id);panel.tabIndex=0;list.after(panel);let next=panel.nextSibling;while(next&&!next.classList?.contains('footer-note')){const following=next.nextSibling;panel.append(next);next=following}active.scrollIntoView?.({block:'nearest',inline:'nearest'})}
function uiSync(){uiWireSearch();uiBindTabs(document.querySelector('.tabs[aria-label="Informações do veículo"]'),'vehicle-tab','Informações do veículo');uiBindTabs(document.querySelector('.school-tabs'),'school-tab','Áreas de chamadas');const grid=document.getElementById('vehicle-grid'),search=document.getElementById('search');if(grid&&search){let status=document.getElementById('vehicle-search-status');if(!status){status=document.createElement('p');status.id='vehicle-search-status';status.className='search-summary';status.setAttribute('role','status');status.setAttribute('aria-live','polite');grid.before(status)}const count=grid.querySelectorAll('[data-vehicle-card]').length,text=search.value?count+' veículo(s) encontrado(s).':'';if(status.textContent!==text)status.textContent=text;status.hidden=!text}}
const originalConventionsShell=shell;shell=function(){const tabFocus=document.activeElement?.dataset?.uiTab;originalConventionsShell();if(novaAuth.stage!=='ready')return;uiSync();if(tabFocus)document.getElementById(tabFocus)?.focus({preventScroll:true})};
document.addEventListener('click',event=>{const detail=event.target.closest?.('[data-action="detail"]');if(detail&&!saving){const id=detail.dataset.id;Promise.resolve().then(()=>{if(selected!==id)return;const title=document.querySelector('.content h1');title?.setAttribute('tabindex','-1');title?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'})})}const open=uiCardPrimaryTarget(event);if(open&&!saving)open.click()});
let uiSyncQueued=false;const uiObserver=new MutationObserver(()=>{if(uiSyncQueued)return;uiSyncQueued=true;Promise.resolve().then(()=>{uiSyncQueued=false;uiSync()})});for(const id of ['app','modal']){const root=document.getElementById(id);if(root)uiObserver.observe(root,{childList:true,subtree:true})}uiSync();
